<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {Button,Input,NativeSelect,Dialog,HelpTip,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {currentUiTarget} from '../../agent-repo-api/ui-navigation.mjs';
import type {EntityType,EntityRecord,DirectorySyncRun,EntityService,EntitySyncProvider} from '../../agent-repo-api/entities.mjs';
import {useManagementRequest} from './management-request';
import AuditView from './AuditView.vue';
import type {AuditPage} from './audit-model';
import PeoplePage from './PeoplePage.vue';
import EntityRelations from './EntityRelations.vue';
const props=defineProps<{agentId?:string;embedded?:boolean}>();
const context=useHostContext(),agent=computed(()=>props.agentId??currentUiTarget({...context.value,props:{agentId:context.value.props.agentId}}).agentId??''),embedded=computed(()=>props.embedded||!!context.value.props.embeddedManagement);
const safe=(v:unknown)=>context.value.host.redact(String(v??''));
const request=useManagementRequest(context,()=>agent.value,'agent-repo','projects-',()=>`agent:${agent.value}:agent-repo-entities`);
const types=ref<(EntityType&{count:number})[]>([]),sources=ref<{namespace:string;label?:string}[]>([]),page=ref<ReturnType<EntityService['list']>>(),selected=ref<EntityRecord>(),typeId=ref(''),query=ref(''),source=ref(''),offset=ref(0),loading=ref(false),error=ref(''),personMode=ref(false),audit=ref<{targetId:string}>();
const syncOpen=ref(false);
const syncInfo=ref<ReturnType<EntitySyncProvider['info']>>(),syncBusy=ref(false),accountId=ref('');let syncRequestId:string|null=null,epoch=0,syncGeneration=0;
const automatic=computed(()=>syncInfo.value?.automatic as (NonNullable<ReturnType<EntitySyncProvider['info']>['automatic']>&{missingDepartmentIds?:string[]})|undefined);
const when=(value?:number)=>value?new Date(value).toLocaleString():'暂无';
const labels:Record<DirectorySyncRun['status'],string>={running:'正在同步全部部门',completed:'上次全量同步完成',partial:'部分完成，资料仍不完整',failed:'同步失败',unknown:'上次同步结果待核查'};
const kinds={channel:'渠道采集',program:'程序同步',ai:'AI 同步',manual:'人工维护'};
const scope=computed(()=>[agent.value,context.value.presented,context.value.host.connection.canRead,context.value.host.connection.canWrite].join('|'));
const readable=computed(()=>!!agent.value&&context.value.presented&&context.value.host.connection.canRead);
const allTypes=computed(()=>[{id:'',label:'全部资料',count:types.value.reduce((n,t)=>n+t.count,0)},...types.value]);
const fieldName=(name:string)=>types.value.find(t=>t.id===selected.value?.typeId)?.fields?.[name]?.label??({giteaUsername:'Gitea 账号',giteaSource:'账号映射来源'} as Record<string,string>)[name]??name;
const display=(value:unknown)=>safe(Array.isArray(value)?value.join('、'):value===null||value===undefined||value===''?'暂未获取':value);
async function refresh(){if(!readable.value||personMode.value)return;const token=++epoch,valid=request.capture();loading.value=true;error.value='';page.value=undefined;selected.value=undefined;try{try{const info=await request.invoke<ReturnType<EntitySyncProvider['info']>>('directorySyncInfo',accountId.value?{accountId:accountId.value}:{});if(!valid()||token!==epoch)return;syncInfo.value=Array.isArray(info.accounts)?info:undefined;if(!accountId.value&&info.accounts?.length===1)accountId.value=info.accounts[0]!.accountId;}catch{if(!valid()||token!==epoch)return;syncInfo.value={available:false,accounts:[],run:null,reason:'组织同步状态读取失败'};}
 const [catalog,next]=await Promise.all([request.invoke<ReturnType<EntityService['types']>>('entityTypes',{}),request.invoke<ReturnType<EntityService['list']>>('entities',{...(typeId.value?{typeId:typeId.value}:{}),...(query.value.trim()?{query:query.value.trim()}:{}),...(source.value.trim()?{source:source.value.trim()}:{}),offset:offset.value,limit:20})]);if(!valid()||token!==epoch)return;types.value=catalog.types;sources.value=catalog.sources??[...new Set(next.entities.map(r=>r.source.namespace))].map(namespace=>({namespace}));page.value=next;selected.value=next.entities[0];}catch(e){if(valid()&&token===epoch)error.value=safe(e instanceof Error?e.message:e);}finally{if(valid()&&token===epoch)loading.value=false;}}
async function syncDirectory(){if(syncBusy.value||!context.value.host.connection.canWrite||!syncInfo.value?.available)return;const valid=request.capture(),token=epoch,syncToken=++syncGeneration;syncRequestId??=crypto.randomUUID();syncBusy.value=true;try{const run=await request.invoke<DirectorySyncRun>('directorySync',{...(accountId.value?{accountId:accountId.value}:{}),requestId:syncRequestId});if(!valid()||syncToken!==syncGeneration)return;syncRequestId=null;if(token!==epoch)return;syncInfo.value={...syncInfo.value,run};}catch(e){if(valid()&&token===epoch)error.value=safe(e instanceof Error?e.message:e);}finally{if(syncToken===syncGeneration)syncBusy.value=false;}}
function selectAgent(value:unknown){const id=String(value);context.value.host.agents.select(id);if(context.value.props.agentId)context.value.host.navigation.openPage({id:'entities',params:{agentId:id}});}
function search(){offset.value=0;void refresh();}
function openPeople(){epoch++;request.invalidate();personMode.value=true;}
function accountChanged(){syncGeneration++;syncBusy.value=false;syncRequestId=null;void refresh();}
const auditInvoke=(action:string,payload:Record<string,unknown>)=>request.invoke<AuditPage>(action,payload);
watch(scope,()=>{epoch++;syncGeneration++;request.invalidate();types.value=[];sources.value=[];page.value=undefined;selected.value=undefined;typeId.value='';query.value='';source.value='';offset.value=0;personMode.value=false;audit.value=undefined;syncInfo.value=undefined;syncBusy.value=false;syncRequestId=null;accountId.value='';syncOpen.value=false;loading.value=false;error.value='';void refresh();},{flush:'sync'});
onMounted(refresh);onBeforeUnmount(()=>{epoch++;syncGeneration++;});
</script>
<template><section class="ar-entities" aria-label="Agent 实体资料库" :aria-busy="loading"><header class="ar-entities-header" :class="{'ar-section-heading':embedded}"><div><component :is="embedded?'h2':'h1'">实体资料库</component><p>AI 与程序共同维护的结构化资料，按类型组织，跨会话查询。</p></div><div class="ar-heading-actions"><HelpTip title="实体资料说明"><p>资料由 AI 与程序按来源同步维护，在详情中查看采集时间与来源。相同来源更新原记录，不按名称合并。</p></HelpTip><Button v-if="syncInfo" variant="outline" aria-haspopup="dialog" aria-label="组织同步管理" @click="syncOpen=true">组织同步管理<span v-if="syncInfo?.automatic?.lastError||['partial','failed','unknown'].includes(syncInfo?.run?.status??'')" class="ar-warning">需关注</span></Button><Button variant="outline" @click="audit={targetId:''}">查看审计</Button></div><NativeSelect v-if="!embedded" :model-value="agent" aria-label="实体资料库所属 Agent" @update:model-value="selectAgent"><option v-for="a in context.host.agents.rows??[{id:agent}]" :key="a.id" :value="a.id">{{safe(a.name??a.id)}}</option></NativeSelect><Button v-if="embedded&&!personMode" variant="outline" :disabled="loading" @click="refresh">刷新资料</Button></header>
<template v-if="context.presented"><p v-if="!context.host.connection.canRead" class="ar-error">需要 operator.read 权限才能查看实体资料库。</p><p v-else-if="!agent">请先选择一个 Agent。</p><template v-else><p v-if="!embedded" class="ar-meta">{{safe('Agent '+agent+' · 跨会话共享 · 与其他 Agent 隔离')}}</p><template v-if="personMode"><Button class="ar-entities-back" variant="ghost" @click="personMode=false;refresh()">返回实体资料库</Button><PeoplePage :agent-id="agent" embedded/></template><template v-else>
<form class="ar-entities-toolbar" @submit.prevent="search"><Input v-model="query" aria-label="搜索实体" placeholder="搜索名称、摘要或属性"/><NativeSelect v-model="source" aria-label="实体来源"><option value="">全部来源</option><option v-for="item in sources" :key="item.namespace" :value="item.namespace">{{safe(item.label??(item.namespace==='feishu'?'飞书':item.namespace))}}</option></NativeSelect><Button type="submit" :disabled="loading">搜索</Button><Button v-if="!embedded" variant="outline" :disabled="loading" @click="refresh">刷新资料</Button></form>

<div class="ar-entities-layout"><nav class="ar-entity-types" aria-label="实体类型"><Button v-for="type in allTypes" :key="type.id" variant="ghost" :aria-current="typeId===type.id?'page':'false'" @click="typeId=type.id;search()"><span>{{safe(type.label)}}</span><span>{{type.count}}</span></Button><p class="ar-description">按类型整理人员、组织与资源，资料随来源同步更新。</p></nav><div class="ar-entities-workspace"><div class="ar-entities-result-heading"><strong>{{safe(types.find(t=>t.id===typeId)?.label??'全部资料')}}</strong><span class="ar-meta">{{page?page.total+' 条资料':loading?'正在读取…':'未读取'}}</span><Button v-if="typeId==='person'" variant="outline" @click="openPeople">飞书人员同步与更正</Button></div><p :class="error?'ar-error':'ar-entities-notice'" :role="error&&!syncOpen?'alert':'status'">{{error||'资料由各来源同步维护，可在详情中查看采集时间与来源。'}}</p><Button v-if="error" variant="outline" @click="refresh">重试读取</Button><template v-else><div v-if="!page?.entities.length" class="ar-entities-empty">{{loading?'正在加载资料…':query||source?'没有匹配资料，请调整搜索条件。':'此分类暂无资料。AI 或程序完成同步后会自动出现在这里。'}}</div><div v-else class="ar-entities-content"><div class="ar-entities-list" aria-label="实体列表"><button v-for="record in page.entities" :key="record.id" type="button" :aria-pressed="selected?.id===record.id" @click="selected=record"><strong>{{safe(record.name)}}</strong><span>{{safe((types.find(t=>t.id===record.typeId)?.label??record.typeId)+' · '+record.source.namespace)}}</span><small>{{safe(record.summary||'暂无摘要')}}</small></button></div><article v-if="selected" :key="selected.id" class="ar-entity-detail"><div class="ar-entity-detail-heading"><h3>{{safe(selected.name)}}</h3><span class="ar-entity-origin">{{kinds[selected.source.kind]??'未知来源'}}</span><Button variant="ghost" @click="audit={targetId:selected.id}">修改日志</Button></div><p>{{safe(selected.summary||'暂无摘要')}}</p><dl><div v-for="(value,name) in selected.attributes" :key="name"><dt>{{safe(fieldName(name))}}</dt><dd>{{display(value)}}</dd></div></dl><details><summary>来源与同步信息</summary><dl><div v-for="[label,value] in [['来源标识',selected.source.namespace],['来源记录 ID',selected.source.externalId],['采集时间',selected.observedAt],['更新时间',selected.updatedAt],['实体 ID',selected.id],['修订版本',selected.revision]]" :key="label"><dt>{{label}}</dt><dd>{{safe(value)}}</dd></div></dl></details><EntityRelations :id="selected.id" :invoke="request.invoke" :safe="safe"/><Button v-if="selected.legacyPersonId" variant="outline" @click="openPeople">打开飞书人员管理</Button><p v-else class="ar-description">由来源同步更新。相同来源记录会更新原实体，不按名称自动合并。</p></article></div><div class="ar-entities-pagination"><Button v-if="offset" variant="outline" @click="offset=Math.max(0,offset-20);refresh()">上一页</Button><Button v-if="page?.nextOffset!==null&&page?.nextOffset!==undefined" variant="outline" @click="offset=page.nextOffset;refresh()">下一页</Button></div></template></div></div></template></template></template>
<Dialog size="detail" :session-scoped="false" v-model:open="syncOpen" title="组织同步管理" description="飞书组织与部门目录"><section v-if="syncInfo" class="ar-entities-sync"><NativeSelect v-if="syncInfo.accounts.length>1" v-model="accountId" aria-label="组织同步飞书账号" :disabled="syncBusy" @update:model-value="accountChanged"><option value="">选择飞书账号</option><option v-for="account in syncInfo.accounts" :key="account.accountId" :value="account.accountId">{{safe(account.accountId)}}</option></NativeSelect><template v-if="automatic"><p>{{safe('自动同步'+(automatic.enabled?'已启用':'已关闭')+' · 待处理 '+automatic.pending+' · 部门事件'+(automatic.eventSubscription==='observed'?'已收到':'订阅待验证'))}}</p><p>{{safe('上次完整校准：'+when(automatic.lastFullSuccessAt)+' · 组织更新：'+when(automatic.lastOrganizationSuccessAt))}}</p><p v-if="automatic.missingDepartmentIds?.length">{{automatic.missingDepartmentIds.length}} 个部门本次未发现，已保留历史关系待核验</p><p v-if="automatic.lastError" class="ar-error">{{safe('自动同步异常：'+automatic.lastError)}}</p></template><p>{{safe(syncInfo.run?labels[syncInfo.run.status]+' · 部门 '+syncInfo.run.storedDepartments+'/'+syncInfo.run.departments+' · 组织 '+(syncInfo.run.organizationId?'已取得':'未取得'):syncInfo.reason??'尚未同步完整组织目录')}}</p><p v-for="(issue,index) in syncInfo.run?.errors" :key="index" class="ar-error">{{safe((issue.requiredScopes?.length?'缺少权限：'+issue.requiredScopes.join('、'):issue.reason??issue.stage)+(issue.code!==undefined?'（'+issue.code+'）':''))}}</p><Button :disabled="!context.host.connection.canWrite||!syncInfo.available||syncBusy||syncInfo.run?.status==='running'||syncInfo.accounts.length>1&&!accountId" @click="syncDirectory">同步飞书组织与全部部门</Button><small>从组织根目录逐级读取全部部门；刷新资料可查看进度，权限不足或中途失败不会按缺失结果断联。</small></section><p v-if="error" role="alert" class="ar-error">{{error}}</p></Dialog>
<Dialog size="wide" :open="!!audit" title="实体修改审计" @update:open="audit=undefined"><AuditView v-if="audit" :invoke="auditInvoke" :safe="safe" feature="entities" :target-id="audit.targetId"/></Dialog>
</section></template>
